#include <bits/stdc++.h>
using namespace std;

bool check(const string& s, int L) {
    int n = (int)s.size();
    string cur = s.substr(0, L);
    int pos = L;

    while (pos < n) {
        int i = (int)cur.size() - 1;
        while (i >= 0 && cur[i] == '9') {
            cur[i] = '0';
            --i;
        }
        if (i < 0) {
            cur.insert(cur.begin(), '1');
        } else {
            ++cur[i];
        }

        int len = (int)cur.size();
        if (pos + len > n) return false;
        if (s.compare(pos, len, cur) != 0) return false;
        pos += len;
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    string s;
    s.reserve(N);

    for (int i = 0; i < N; ++i) {
        int d;
        cin >> d;
        s.push_back(char('0' + d));
    }

    for (int L = 1; L <= N; ++L) {
        if (s[0] == '0') continue;
        if (check(s, L)) {
            cout << s.substr(0, L) << '\n';
            return 0;
        }
    }

    return 0;
}
